srv.stderr.on('data', d => process.stdout.write('[srv-err] ' + d));

const wait = ms => new Promise(r => setTimeout(r, ms));
function client(name) {
  const ws = new WebSocket(`ws://localhost:${PORT}/ws`);
  ws.msgs = [];
  ws.on('message', raw => { const m = JSON.parse(raw); ws.msgs.push(m); console.log(`[${name}]`, JSON.stringify(m)); });
  return new Promise((res, rej) => { ws.on('open', () => res(ws)); ws.on('error', rej); });
}
(async () => {
  await wait(500);
  const a = await client('A');
  a.send(JSON.stringify({ t: 'create', name: 'Alice', map: 'foundry' }));
  await wait(200);
  const created = a.msgs.find(m => m.t === 'created');
  if (!created) throw new Error('no created');
  const b = await client('B');
  b.send(JSON.stringify({ t: 'join', code: created.code, name: 'Bob' }));
  await wait(200);
  const joined = b.msgs.find(m => m.t === 'joined');
