  await wait(200);
  const death = b.msgs.find(m => m.t === 'death');
  const dmg = b.msgs.find(m => m.t === 'damage');
  const scores = b.msgs.find(m => m.t === 'scores');
  if (!death || death.id !== joined.id || death.by !== created.id || !death.head) throw new Error('death wrong');
  if (!dmg || dmg.hp !== 0) throw new Error('damage wrong');
  if (!scores) throw new Error('no scores');
  // respawn
  b.send(JSON.stringify({ t: 'respawn' }));
  await wait(200);
  if (!a.msgs.find(m => m.t === 'respawned' && m.id === joined.id && m.hp === 100)) throw new Error('respawn wrong');
  console.log('ALL TESTS PASSED');
  srv.kill();
  process.exit(0);
})().catch(e => { console.error('FAIL:', e.message); srv.kill(); process.exit(1); });
